SELECT * FROM logs WHERE EventID=1 AND (EventID=1 AND ((Image LIKE '%\\schtasks.exe' ESCAPE '\' AND CommandLine LIKE '%/create%' ESCAPE '\') AND (ParentImage LIKE '%\\cmd.exe' ESCAPE '\' OR ParentImage LIKE '%\\powershell.exe' ESCAPE '\' OR ParentImage LIKE '%\\pwsh.exe' ESCAPE '\' OR ParentImage LIKE '%\\wscript.exe' ESCAPE '\' OR ParentImage LIKE '%\\cscript.exe' ESCAPE '\' OR ParentImage LIKE '%\\mshta.exe' ESCAPE '\')))
